// 하이드레이션 불일치가 생기는 흔한 예
function Welcome() {
  // 서버는 UTC, 브라우저는 로컬 시간대라 서버·클라이언트 결과가 다를 수 있음
  return <p>{new Date().toLocaleTimeString()}</p>;
}

// 해결: 서버에서는 안 그리고, 마운트 후에만 그리기
function Welcome() {
  const [time, setTime] = useState(null);
  useEffect(() => setTime(new Date().toLocaleTimeString()), []);
  return <p>{time ?? "..."}</p>;
}
